import java.io.*;
import java.util.*;

public class Main {
    static final int MAX_SIZE = 7100;
    static final long INF = 1000000000L;
    static char[][] g1 = new char[14][14];
    static char[][] g2 = new char[14][14];
    static boolean[][] visited = new boolean[14][14];
    static int[][] dist = new int[14][14];
    static int n;
    static int[] tgt;

    static class Maxflow {
        static class Edge {
            int from, to;
            long flow, cap;
            Edge(int from, int to, long cap) {
                this.from = from;
                this.to = to;
                this.cap = cap;
                this.flow = 0;
            }
        }

        int s, t;
        ArrayList<Edge> edg;
        ArrayList<Integer>[] g;
        int[] distM, visitedM, curM;

        @SuppressWarnings("unchecked")
        Maxflow() {
            edg = new ArrayList<>();
            g = new ArrayList[MAX_SIZE];
            for (int i = 0; i < MAX_SIZE; i++) g[i] = new ArrayList<>();
            distM = new int[MAX_SIZE];
            visitedM = new int[MAX_SIZE];
            curM = new int[MAX_SIZE];
        }

        void addEdge(int from, int to, long cap) {
            Edge e1 = new Edge(from, to, cap);
            Edge e2 = new Edge(to, from, 0);
            edg.add(e1);
            edg.add(e2);
            g[from].add(edg.size() - 2);
            g[to].add(edg.size() - 1);
        }

        boolean bfs() {
            Arrays.fill(visitedM, 0);
            Arrays.fill(distM, 0);
            Queue<Integer> q = new LinkedList<>();
            q.add(s);
            visitedM[s] = 1;
            distM[s] = 0;
            while (!q.isEmpty()) {
                int v = q.poll();
                for (int idx : g[v]) {
                    Edge e = edg.get(idx);
                    int nxt = e.to;
                    if (visitedM[nxt] == 0 && e.cap > e.flow) {
                        distM[nxt] = distM[v] + 1;
                        q.add(nxt);
                        visitedM[nxt] = 1;
                    }
                }
            }
            return visitedM[t] == 1;
        }

        long dfs(int x, long cp) {
            if (x == t || cp == 0) return cp;
            long flow = 0, newflow;
            for (int i = curM[x]; i < g[x].size(); i = curM[x]) {
                Edge e = edg.get(g[x].get(i));
                if (distM[x] + 1 == distM[e.to]) {
                    long minn = Math.min(cp, e.cap - e.flow);
                    newflow = dfs(e.to, minn);
                    if (newflow > 0) {
                        e.flow += newflow;
                        edg.get(g[x].get(i) ^ 1).flow -= newflow;
                        flow += newflow;
                        cp -= newflow;
                        if (cp == 0) break;
                    }
                }
                curM[x]++;
            }
            return flow;
        }

        long Dinic() {
            long flow = 0;
            while (bfs()) {
                Arrays.fill(curM, 0);
                flow += dfs(s, INF);
            }
            return flow;
        }
    }

    static void BFS(int x, int y) {
        for (int i = 0; i < 14; i++) {
            Arrays.fill(dist[i], 111);
            Arrays.fill(visited[i], false);
        }
        Queue<int[]> q = new LinkedList<>();
        q.add(new int[]{x, y, 0});
        dist[x][y] = 0;
        int[] dx = {1, 0, 0, -1};
        int[] dy = {0, 1, -1, 0};
        while (!q.isEmpty()) {
            int[] p = q.poll();
            int cx = p[0], cy = p[1], d = p[2];
            if (visited[cx][cy]) continue;
            visited[cx][cy] = true;
            dist[cx][cy] = d;
            for (int i = 0; i < 4; i++) {
                int tx = cx + dx[i], ty = cy + dy[i];
                if (tx <= 0 || tx > n || ty <= 0 || ty > n || visited[tx][ty] || g1[tx][ty] == 'Y') continue;
                q.add(new int[]{tx, ty, d + 1});
            }
        }
    }

    static int index(int level, int x, int y) {
        return level * n * n + (x - 1) * n + y;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        int T = Integer.parseInt(st.nextToken());

        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                g1[i][j] = line.charAt(j - 1);
            }
        }
        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                g2[i][j] = line.charAt(j - 1);
            }
        }

        Maxflow mf = new Maxflow();
        mf.s = 0;
        mf.t = MAX_SIZE - 2;

        int x = 0, y = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (g1[i][j] == 'Z') {
                    x = i; y = j;
                    break;
                }
            }
            if (x != 0) break;
        }

        tgt = new int[n * n + 1];
        for (int i = 1; i <= n * n; i++) {
            tgt[i] = MAX_SIZE - 3 - (n * n - i);
        }

        BFS(x, y);

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (g1[i][j] >= '0' && g1[i][j] <= '9')
                    mf.addEdge(mf.s, index(0, i, j), g1[i][j] - '0');
                if (g2[i][j] >= '0' && g2[i][j] <= '9')
                    mf.addEdge(tgt[index(0, i, j)], mf.t, g2[i][j] - '0');
                mf.addEdge(index(0, i, j), tgt[index(0, i, j)], INF);
            }
        }

        int[] dx = {1, 0, 0, -1};
        int[] dy = {0, 1, -1, 0};
        for (int level = 1; level <= T; level++) {
            for (int j = 1; j <= n; j++) {
                for (int k = 1; k <= n; k++) {
                    if (g1[j][k] == 'Y' || g1[j][k] == 'Z') continue;
                    for (int l = 0; l < 4; l++) {
                        int tx = j + dx[l], ty = k + dy[l];
                        if (tx >= 1 && tx <= n && ty >= 1 && ty <= n && g1[tx][ty] != 'Y' && g1[tx][ty] != 'Z') {
                            if (dist[j][k] >= level && dist[tx][ty] >= level) {
                                mf.addEdge(index(level - 1, tx, ty), index(level, j, k), INF);
                            }
                        }
                    }
                    mf.addEdge(index(level, j, k), tgt[index(0, j, k)], INF);
                }
            }
        }

        System.out.println(mf.Dinic());
    }
}
